"""Execute Python programs generated by the LLM."""

from __future__ import annotations

from dsh import ExecResult, run_python


def _strip_code_fence(reply: str) -> str:
    """Remove one surrounding Python Markdown fence when present."""
    code = reply.strip()
    lines = code.splitlines()

    if len(lines) < 2:
        return code

    opening = lines[0].strip().lower()
    closing = lines[-1].strip()
    if opening in {"```", "```py", "```python"} and closing == "```":
        return "\n".join(lines[1:-1]).strip()

    return code


def execute_program(
    reply: str,
    file_paths: list[str],
    timeout_s: float = 8.0,
) -> ExecResult:
    """Execute one generated program beside its task files."""
    code = _strip_code_fence(reply)
    return run_python(code, file_paths, timeout_s=timeout_s)
